CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'ADMIN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Person" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"title" TEXT,"function" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Trip" ("id" TEXT PRIMARY KEY,"project" TEXT,"entity" TEXT,"destination" TEXT NOT NULL,"origin" TEXT,"startDate" TIMESTAMP(3),"endDate" TIMESTAMP(3),"status" TEXT NOT NULL DEFAULT 'Option',"hotel" TEXT,"transport" TEXT,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Contact" ("id" TEXT PRIMARY KEY,"city" TEXT NOT NULL,"name" TEXT NOT NULL,"organization" TEXT,"title" TEXT,"email" TEXT);
CREATE TABLE "Meeting" ("id" TEXT PRIMARY KEY,"tripId" TEXT NOT NULL REFERENCES "Trip"("id") ON DELETE CASCADE,"contactId" TEXT REFERENCES "Contact"("id") ON DELETE SET NULL,"personName" TEXT NOT NULL,"project" TEXT,"entity" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 1,"priority" TEXT NOT NULL DEFAULT 'Medium',"status" TEXT NOT NULL DEFAULT 'Proposed',"meetingTime" TEXT,"agenda" TEXT,"attendees" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[]);
CREATE TABLE "MeetingMaterial" ("id" TEXT PRIMARY KEY,"meetingId" TEXT NOT NULL REFERENCES "Meeting"("id") ON DELETE CASCADE,"description" TEXT NOT NULL,"owner" TEXT,"completed" BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE "TeamPlanEntry" ("id" TEXT PRIMARY KEY,"personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE CASCADE,"startDate" TIMESTAMP(3),"endDate" TIMESTAMP(3),"destination" TEXT,"type" TEXT NOT NULL DEFAULT 'Option',"approval" TEXT,"notes" TEXT);
CREATE TABLE "Flight" ("id" TEXT PRIMARY KEY,"personId" TEXT REFERENCES "Person"("id") ON DELETE SET NULL,"tripId" TEXT REFERENCES "Trip"("id") ON DELETE SET NULL,"origin" TEXT NOT NULL,"destination" TEXT NOT NULL,"flightNumber" TEXT,"flightDate" TIMESTAMP(3),"departTime" TEXT,"arriveTime" TEXT,"aircraft" TEXT,"status" TEXT NOT NULL DEFAULT 'Proposed');
CREATE INDEX "Contact_city_idx" ON "Contact"("city");
